#!/usr/bin/env python3
# luxarch:land-queue hook v3 - DO NOT edit this file - it is emitted by `luxarch --emit hooks`; re-emit to update.
"""The land queue: many agents' finished branches gated once, together, on the tree that lands.

`worktree.py ready` (in an issue's worktree) rebases the branch onto the base and records it as ready;
the agent runs no full gate. `worktree.py queue` (from the main checkout) takes every ready branch,
merges them in order onto the newest base in its own worktree (`<agents home>/land-queue`), and gates
that merged tree once:

- the repo's gate (`[agents] land_gate`, `make check` by default) must pass, except the guard legs
  (`lint`, `arch`, `audit`), which fail while the repo still has reds;
- those pass only when each guard says no count of its own rose: the ratchet command (`[agents]
  land_ratchet`, `make land-ratchet`, given `BASE_TREE=<a checkout of the base's tip>`) runs
  `luxarch --ratchet`, `luxlint --ratchet` and `luxaudit --ratchet`, each scanning the base's
  checkout and the batch with one image, so both sides are judged by the same guard code. The
  status command (`[agents] land_status`, `make status`) regenerates the batch's status files. Each guard judges
  its own counts; this file reads none of them.

Green: the batch's regenerated status files are committed, and `worktree.py land` lands it (fetch,
fast-forward, push). Each branch merges as itself, so its commits are on the base and `list --prune`
removes its worktree. Red, or a land that `land` refuses for the batch's own reason: the gate runs
once more (a flaky test is not a culprit), then the batch is split until the culprit is one branch,
handed back with the reason and the log; the rest land. Before blaming a lone branch the bare base is
gated once: a base that fails by itself stops the run. A branch that conflicts with one ahead of it waits for a run on the settled base. A
state outside the batch (the main checkout dirty, origin unreachable, origin holding the batch while
the local base diverged) stops the run, every branch left ready.

Records live in the repository's shared git directory (`<git common dir>/luxarch-land-queue/`):
`ready/` one file per waiting branch, `done/` its outcome (landed, with the landed commits as the
close-out takes them, or handed back, with the reason and the log). `worktree.py queue --status`
prints both. One queue runs at a time (a lock in that directory).

Python 3.9 and the standard library only, like the `worktree` tool that imports it.
"""

from __future__ import annotations

import contextlib
import io
import json
import os
import re
import shlex
import subprocess
import sys
import time
from collections.abc import Callable, Iterator
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent))
from _worktree_git import (  # sibling helper, loaded by path
    agents_home,
    out,
    run,
    run_net,
)

QUEUE_DIR = "luxarch-land-queue"
# a name docker accepts where a recipe names containers after the checkout
BATCH_NAME = "land-queue"
BATCH_BRANCH = "luxarch-land-queue/batch"
# the gate legs that fail while a repo still has guard reds: each guard's own ratchet judges them
GUARD_LEGS = ("lint", "arch", "audit")
# each guard leg's status file: a failed leg passes only when its guard's ratchet judged that file
# on the base and on the batch
LEG_FILES = {
    "lint": ".luxlint-status.json",
    "arch": ".luxarch-status.json",
    "audit": ".luxaudit-status.json",
}
_MAKE_TRAILER = re.compile(r"make(\[\d+\])?: \*\*\* ")
STATUS_FILES = (".luxarch-status.json", ".luxlint-status.json", ".luxaudit-status.json")
# the emitted gate's own summary, as the whole line: a test's output quoting it is not it
_FAILED_LEGS = re.compile(
    r"^(?:\x1b\[[0-9;]*m)*(?:\u2717 )?make check FAILED: ([\w -]+?) \(every leg ran"
)
_RECORD_ERRORS = (OSError, ValueError)
_LOCK_ERRORS = (OSError, ImportError)
# how often a batch is rebuilt when the base moves between its gate and its land
_REBUILDS = 3


# the `land-ratchet` recipe's last line: the guards' combined exit (0 none rose, 1 a count rose,
# 2 a guard reached no verdict and none rose)
_RATCHET_VERDICT = re.compile(r"^land-ratchet verdict: ([0-9])$", re.M)


class Unjudgeable(RuntimeError):
    """The base's own status could not be produced, or the base fails the gate by itself:
    nothing in the batch can be judged."""


# a run that cannot judge or cannot set up its batch: every branch stays ready
_RUN_ERRORS = (Unjudgeable, RuntimeError)


def queue_dir(main: Path) -> Path:
    common = out(main, "rev-parse", "--git-common-dir") or ".git"
    path = Path(common)
    return (path if path.is_absolute() else main / path) / QUEUE_DIR


def _slug(branch: str) -> str:
    """The branch's record name: every byte outside [A-Za-z0-9._-] percent-encoded, so two
    branches never share one."""
    return "".join(
        c
        if re.fullmatch(r"[A-Za-z0-9._-]", c)
        else "".join(f"%{b:02X}" for b in c.encode())
        for c in branch
    )


def _write(path: Path, data: dict[str, object]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_suffix(f".{os.getpid()}.tmp")
    tmp.write_text(json.dumps(data, indent=1, sort_keys=True) + "\n", encoding="utf-8")
    tmp.replace(path)


def _read(path: Path) -> dict[str, object] | None:
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except _RECORD_ERRORS:
        return None
    return data if isinstance(data, dict) else None


def _when(record: dict[str, object], key: str) -> float:
    """A record's timestamp (seconds since the epoch); 0 when it holds none."""
    value = record.get(key)
    return float(value) if isinstance(value, (int, float)) else 0.0


def _records(folder: Path) -> list[dict[str, object]]:
    if not folder.is_dir():
        return []
    found = [_read(p) for p in sorted(folder.glob("*.json"))]
    return [r for r in found if r and isinstance(r.get("branch"), str)]


def agents_setting(main: Path, key: str) -> str:
    """A string under `[agents]` in the main checkout's `.luxarch.toml` (text, no tomllib on 3.9)."""
    try:
        text = (main / ".luxarch.toml").read_text(encoding="utf-8", errors="replace")
    except OSError:
        return ""
    table = ""
    for raw in text.lstrip("﻿").splitlines():
        line = raw.split("#", 1)[0].strip()
        if line.startswith("["):
            table = line.strip("[] ")
            continue
        m = re.match(rf'{re.escape(key)}\s*=\s*"([^"]*)"\s*$', line)
        if table == "agents" and m:
            return m.group(1)
    return ""


# ── ready: the worker's last step ─────────────────────────────────────────────────────────────────


def mark_ready(main: Path, here: Path, branch: str, base: str) -> int:
    """Rebase `branch` onto the local base when it moved, then record it as ready. The caller has
    already refused a dirty worktree, the main checkout and a detached HEAD."""
    local = f"refs/heads/{base}"
    behind = out(here, "rev-list", "--count", f"HEAD..{local}") or "0"
    if behind != "0":
        r = run(here, "rebase", local)
        if r.returncode != 0:
            run(here, "rebase", "--abort")
            print(
                f"REFUSING: rebasing {branch} onto {base} conflicts; nothing changed. Resolve it here "
                f"(`git rebase {base}`, fix, `git rebase --continue`), then run ready again.\n"
                + (r.stdout + r.stderr).strip(),
                file=sys.stderr,
            )
            return 1
        print(f"Rebased {branch} onto {behind} new commit(s) from {base}.")
    ahead = out(here, "rev-list", "--count", f"{local}..HEAD") or "0"
    if ahead == "0":
        print(f"Nothing to land: {branch} has no commits that {base} lacks.")
        return 0
    head = out(here, "rev-parse", "HEAD")
    qdir = queue_dir(main)
    with contextlib.suppress(OSError):
        (qdir / "done" / f"{_slug(branch)}.json").unlink()
    _write(
        qdir / "ready" / f"{_slug(branch)}.json",
        {
            "branch": branch,
            "head": head,
            "base_at": out(here, "rev-parse", local),
            "worktree": str(here),
            "queued_at": time.time(),
        },
    )
    print(
        f"Ready: {branch} at {head[:8]} ({ahead} commit(s)) waits in the land queue, which gates it "
        "with the other ready branches on the tree that lands. Run no full gate here. The queue runs "
        "from the main checkout: `python3 .claude/hooks/worktree.py queue`. Its outcome for this branch: "
        "`python3 .claude/hooks/worktree.py queue --status`. A new commit here makes the record stale: "
        "run ready again after it."
    )
    return 0


# ── the queue ────────────────────────────────────────────────────────────────────────────────────


@contextlib.contextmanager
def _queue_lock(qdir: Path) -> Iterator[bool]:
    qdir.mkdir(parents=True, exist_ok=True)
    try:
        import fcntl
    except ImportError:
        yield True
        return
    with open(qdir / "lock", "a+", encoding="utf-8") as fh:
        try:
            fcntl.flock(fh.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
        except OSError:
            yield False
            return
        try:
            yield True
        finally:
            fcntl.flock(fh.fileno(), fcntl.LOCK_UN)


class Batch:
    """The queue's own worktree, reset to the base for every gate run."""

    def __init__(self, main: Path, base: str, link: Callable[[Path], list[str]]):
        self.main = main
        self.base = base
        self.link = link
        self.path = agents_home(main) / BATCH_NAME
        self.base_path = agents_home(main) / f"{BATCH_NAME}-base"

    def reset(self) -> str:
        """Check out the base's tip on the batch branch, clean, and return that tip's sha."""
        tip = out(self.main, "rev-parse", f"refs/heads/{self.base}")
        if not (self.path / ".git").exists():
            self.path.parent.mkdir(parents=True, exist_ok=True)
            run(self.main, "worktree", "prune")
            r = run(
                self.main,
                "worktree",
                "add",
                "-q",
                "-f",
                "-B",
                BATCH_BRANCH,
                str(self.path),
                tip,
            )
            if r.returncode != 0:
                raise RuntimeError((r.stdout + r.stderr).strip())
        run(self.path, "rebase", "--abort")
        run(self.path, "merge", "--abort")
        run(self.path, "checkout", "-q", "-f", "-B", BATCH_BRANCH, tip)
        run(self.path, "reset", "-q", "--hard", tip)
        run(self.path, "clean", "-qfdx")
        at = out(self.path, "rev-parse", "HEAD")
        here = out(self.path, "symbolic-ref", "--quiet", "--short", "HEAD")
        if at != tip or here != BATCH_BRANCH:
            raise RuntimeError(
                f"the batch worktree {self.path} could not be reset to {self.base} ({tip[:8]}): "
                f"it is at {at[:8] or 'nothing'} on {here or 'no branch'}. Remove it "
                "(`git worktree remove --force` on that path) and run the queue again"
            )
        run(
            self.main,
            "worktree",
            "lock",
            "--reason",
            "land queue: a gate runs here",
            str(self.path),
        )
        self.link(self.main)
        return tip

    def base_tree(self, tip: str) -> Path:
        """A detached checkout of the base's tip beside the batch, for the guards' ratchet to scan
        (`BASE_TREE`), reset to `tip` and cleaned for every gate run."""
        if not (self.base_path / ".git").exists():
            run(self.main, "worktree", "prune")
            r = run(
                self.main,
                "worktree",
                "add",
                "-q",
                "-f",
                "--detach",
                str(self.base_path),
                tip,
            )
            if r.returncode != 0:
                raise RuntimeError((r.stdout + r.stderr).strip())
        run(self.base_path, "checkout", "-q", "-f", "--detach", tip)
        run(self.base_path, "reset", "-q", "--hard", tip)
        run(self.base_path, "clean", "-qfdx")
        if out(self.base_path, "rev-parse", "HEAD") != tip:
            raise RuntimeError(
                f"the base checkout {self.base_path} could not be reset to {tip[:8]}: remove it "
                "(`git worktree remove --force` on that path) and run the queue again"
            )
        run(
            self.main,
            "worktree",
            "lock",
            "--reason",
            "land queue: a ratchet reads it",
            str(self.base_path),
        )
        self.link(self.main)
        return self.base_path

    def release(self) -> None:
        run(self.main, "worktree", "unlock", str(self.path))
        run(self.main, "worktree", "unlock", str(self.base_path))

    def merge(self, branch: str, head: str) -> str:
        """Merge one ready branch onto the batch; '' when it merged, else why it cannot. A conflict
        on a status file only is taken from the batch: the queue regenerates them."""
        if run(self.path, "merge-base", "--is-ancestor", "HEAD", head).returncode == 0:
            r = run(self.path, "merge", "-q", "--ff-only", head)
        else:
            r = run(
                self.path,
                "merge",
                "-q",
                "--no-ff",
                "--no-edit",
                "-m",
                f"land: {branch}",
                head,
            )
        if r.returncode == 0:
            return ""
        conflicted = out(self.path, "diff", "--name-only", "--diff-filter=U").split()
        if conflicted and all(p in STATUS_FILES for p in conflicted):
            for p in conflicted:
                run(self.path, "checkout", "--ours", "--", p)
                run(self.path, "add", "--", p)
            done = run(self.path, "commit", "-q", "--no-edit")
            if done.returncode == 0:
                return ""
        run(self.path, "merge", "--abort")
        return (
            f"conflicts with the batch ({', '.join(conflicted[:5]) or 'merge failed'}): rebase onto "
            "the base, resolve, and run ready again\n"
            + (r.stdout + r.stderr).strip()[-1500:]
        )

    def shell(self, command: str, log: Path) -> int:
        with open(log, "a", encoding="utf-8") as fh:
            fh.write(f"\n$ {command}\n")
            fh.flush()
            # an argument list, never a shell: the command is `[agents] land_gate` / `land_status`
            try:
                argv = shlex.split(command)
            except ValueError as exc:
                fh.write(f"luxarch land queue: cannot read the command: {exc}\n")
                return 2
            if not argv:
                fh.write("luxarch land queue: the command is empty\n")
                return 2
            try:
                r = subprocess.run(
                    argv, cwd=str(self.path), stdout=fh, stderr=subprocess.STDOUT
                )
            except OSError as exc:
                fh.write(f"luxarch land queue: cannot run {argv[0]}: {exc}\n")
                return 127
        return r.returncode


def _load_status(root: Path) -> dict[str, dict[str, object]]:
    found: dict[str, dict[str, object]] = {}
    for name in STATUS_FILES:
        data = _read(root / name)
        if data is not None:
            found[name] = data
    return found


class Queue:
    def __init__(
        self,
        main: Path,
        base: str,
        land: Callable[[], int],
        link: Callable[[Path], list[str]],
        record: Callable[[Path, str], dict[str, object]],
    ):
        self.main = main
        self.base = base
        self.land_here = land
        self.record = record
        self.batch = Batch(main, base, link)
        self.qdir = queue_dir(main)
        self.gate = agents_setting(main, "land_gate") or "make check"
        self.status = agents_setting(main, "land_status") or "make status"
        self.ratchet = agents_setting(main, "land_ratchet") or "make land-ratchet"
        self.pushing = agents_setting(main, "push") == "agent" and bool(
            out(main, "remote", "get-url", "origin")
        )
        self.ratchet_ok = False
        self.logs = self.qdir / "logs"
        self.gated_tip = ""
        self.runs = 0
        self.base_checked: dict[str, str] = {}
        self.deferred: list[dict[str, object]] = []
        self.pending: list[dict[str, object]] = []

    # ── outcomes ──
    def _done(
        self,
        member: dict[str, object],
        outcome: str,
        reason: str = "",
        log: str = "",
        commits: list[dict[str, object]] | None = None,
    ) -> None:
        branch = str(member["branch"])
        _write(
            self.qdir / "done" / f"{_slug(branch)}.json",
            {
                "branch": branch,
                "head": member.get("head"),
                "outcome": outcome,
                "reason": reason,
                "log": log,
                "commits": commits or [],
                "at": time.time(),
            },
        )
        ready = self.qdir / "ready" / f"{_slug(branch)}.json"
        now = _read(ready)
        if now is not None and now.get("head") == member.get("head"):
            # a `ready` run since this one was taken holds a newer head: it stays queued
            with contextlib.suppress(OSError):
                ready.unlink()
        print(
            f"  {outcome:<11} {branch}"
            + (f": {reason.splitlines()[0]}" if reason else "")
        )

    # ── one gate run over a set of members ──
    def _gate(
        self, members: list[dict[str, object]], bare: bool = False
    ) -> tuple[str, list[dict[str, object]], str, str]:
        """Build the batch from the base and gate it: ('green'|'red', the members merged, why, log)."""
        self.runs += 1
        stamp = f"{time.strftime('%Y%m%d-%H%M%S')}-{os.getpid()}-{self.runs}"
        self.logs.mkdir(parents=True, exist_ok=True)
        log = self.logs / f"{stamp}-status.log"
        tip = self.batch.reset()
        self.gated_tip = tip
        # the guards this repo keeps status for; their ratchet scans a checkout of the base's tip
        # with the batch's own image, so both sides are judged alike
        base_status = _load_status(self.batch.path)
        base_tree = self.batch.base_tree(tip) if base_status else None
        merged: list[dict[str, object]] = []
        self.deferred = []
        for m in members:
            why = self.batch.merge(str(m["branch"]), str(m["head"]))
            if why and merged:
                # it conflicts with a branch ahead of it, which may yet be handed back: it is
                # gated again on the base the batch settles to
                self.deferred.append(m)
                continue
            if why:
                self._done(m, "handed-back", why, str(log))
                continue
            merged.append(m)
        if not merged and not bare:
            return "empty", [], "", str(log)
        self.ratchet_ok = False
        now: dict[str, dict[str, object]] = {}
        if base_status:
            head = out(self.batch.path, "rev-parse", "HEAD")
            code = self.batch.shell(self.status, log)
            now = _load_status(self.batch.path)
            wrong = [n for n, d in now.items() if str(d.get("commit") or "") != head]
            if code != 0 or wrong:
                run(self.batch.path, "checkout", "-q", "-f", "--", ".")
                why = f"exited {code}" if code else f"did not stamp {', '.join(wrong)}"
                return (
                    "red",
                    merged,
                    f"the status command on the batch {why}: its counts cannot be judged",
                    str(log),
                )
            verdict = self.logs / f"{stamp}-ratchet.log"
            where = shlex.quote(str(base_tree))
            code = self.batch.shell(f"{self.ratchet} BASE_TREE={where}", verdict)
            if code != 0:
                run(self.batch.path, "checkout", "-q", "-f", "--", ".")
                said = verdict.read_text(encoding="utf-8", errors="replace").strip()
                # make exits 2 for any failed recipe: the recipe's own last line carries the guards'
                # verdict (1 a count rose, 2 no verdict). Without it, only a ratchet that exited 1
                # said a count rose: a kill, a missing program or any other exit judged nothing
                said_codes = _RATCHET_VERDICT.findall(said)
                code = int(said_codes[-1]) if said_codes else (1 if code == 1 else 2)
                if code == 2:
                    # a guard that could not judge (its advisory download timed out, its base scan
                    # failed): no branch caused it, so every branch stays ready for the next run
                    raise Unjudgeable(
                        f"the guards' ratchet reached no verdict (exit 2), log {verdict}:\n"
                        + said[-1500:]
                    )
                return (
                    "red",
                    merged,
                    f"a guard count rose (exit {code}):\n" + said[-1500:],
                    str(verdict),
                )
            self.ratchet_ok = True
            if out(self.batch.path, "status", "--porcelain", "--", *STATUS_FILES):
                run(
                    self.batch.path,
                    "add",
                    "--",
                    *[n for n in STATUS_FILES if (self.batch.path / n).exists()],
                )
                run(
                    self.batch.path,
                    "commit",
                    "-q",
                    "-m",
                    "chore(guards): status files for the land batch",
                )
        for attempt in (1, 2):
            log = self.logs / f"{stamp}-gate{attempt}.log"
            code = self.batch.shell(self.gate, log)
            failed = self._failed_legs(log) if code else []
            if code == 0 or (
                failed
                and self.ratchet_ok
                and all(
                    leg in LEG_FILES
                    and LEG_FILES[leg] in base_status
                    and LEG_FILES[leg] in now
                    for leg in failed
                )
            ):
                touched = out(
                    self.batch.path, "status", "--porcelain", "--untracked-files=no"
                )
                if touched:
                    # a gate that rewrites a tracked file judged a tree that is not what lands
                    shown = ", ".join(ln[3:] for ln in touched.splitlines()[:5])
                    return (
                        "red",
                        merged,
                        f"the gate changed tracked files: {shown}",
                        str(log),
                    )
                return "green", merged, "", str(log)
            if attempt == 1:
                print(
                    f"  gate red ({', '.join(failed or []) or f'exit {code}'}): running the gate once more"
                )
        legs = ", ".join(failed or []) or f"the gate exited {code}"
        return "red", merged, f"the gate failed: {legs}", str(log)

    @staticmethod
    def _failed_legs(log: Path) -> list[str] | None:
        """The legs the gate's own summary names: its last `make check FAILED:` line, followed by
        nothing but make's own error lines. A gate that died before its summary names none."""
        try:
            lines = log.read_text(encoding="utf-8", errors="replace").splitlines()
        except OSError:
            return None
        for i in range(len(lines) - 1, -1, -1):
            hit = _FAILED_LEGS.match(lines[i].strip())
            if hit:
                rest = [ln for ln in lines[i + 1 :] if ln.strip()]
                if all(_MAKE_TRAILER.match(ln) for ln in rest):
                    return hit.group(1).split()
                return None
        return None

    def _commits(
        self, member: dict[str, object], before: str
    ) -> list[dict[str, object]]:
        """The member's own commits, from the base it was rebased onto at `ready`."""
        start = str(member.get("base_at") or "") or before
        shas = out(
            self.main, "rev-list", "--reverse", f"{start}..{member['head']}"
        ).split()
        return [self.record(self.main, sha) for sha in shas]

    def _base_red(self) -> str:
        """Why the bare base fails the gate, '' when it passes (asked once per base tip, when a
        lone branch reds: a red base would blame every branch)."""
        tip = out(self.main, "rev-parse", f"refs/heads/{self.base}")
        if tip in self.base_checked:
            return self.base_checked[tip]
        result, _merged, why, log = self._gate([], bare=True)
        verdict = f"{why} (log: {log})" if result == "red" else ""
        self.base_checked[tip] = verdict
        return verdict

    def _outside(
        self,
        merged: list[dict[str, object]],
        gated_head: str,
        before: str,
        log: str,
    ) -> None:
        """Raise when a land refusal is not the batch's: the owner's checkout changed, origin does
        not answer, or origin took the push while the local base could not follow."""
        if out(self.main, "status", "--porcelain", "--untracked-files=no"):
            raise Unjudgeable(
                f"the main checkout ({self.main}) has uncommitted changes to tracked files: the "
                "owner's, so nothing lands until it is clean"
            )
        if not self.pushing:
            return
        r = run_net(
            self.main, "ls-remote", "--heads", "origin", f"refs/heads/{self.base}"
        )
        if r.returncode != 0:
            raise Unjudgeable(
                f"origin does not answer: {(r.stdout + r.stderr).strip()[:300]}"
            )
        if r.stdout.split()[:1] == [gated_head]:
            for m in merged:
                self._done(
                    m,
                    "landed",
                    f"on origin's {self.base}",
                    log,
                    self._commits(m, before),
                )
            raise Unjudgeable(
                f"origin's {self.base} holds the batch, but the local {self.base} diverged from it: "
                "the owner reconciles the main checkout"
            )

    def _land(self) -> tuple[int, str]:
        buf = io.StringIO()
        here = Path.cwd()
        try:
            os.chdir(self.batch.path)
            with contextlib.redirect_stdout(buf), contextlib.redirect_stderr(buf):
                code = self.land_here()
        finally:
            os.chdir(here)
        return code, buf.getvalue()

    def settle(self, members: list[dict[str, object]], depth: int = 0) -> None:
        """Gate `members` together; land them when green, else split until each culprit is alone."""
        for _ in range(_REBUILDS):
            result, merged, why, log = self._gate(members)
            later, self.deferred = self.deferred, []
            if later:
                print(
                    f"  {len(later)} branch(es) conflict with the batch: gated after it settles"
                )
                self.pending += later
            if result == "empty":
                return
            gated_head = out(self.batch.path, "rev-parse", "HEAD")
            if result == "red":
                if len(merged) == 1:
                    red_base = self._base_red()
                    if red_base:
                        raise Unjudgeable(
                            f"the base {self.base} fails the gate by itself: {red_base}"
                        )
                    self._done(merged[0], "handed-back", why, log)
                    return
                half = len(merged) // 2
                print(
                    f"  batch of {len(merged)} red ({why.splitlines()[0]}): splitting it"
                )
                self.settle(merged[:half], depth + 1)
                self.settle(merged[half:], depth + 1)
                return
            before = out(self.main, "rev-parse", f"refs/heads/{self.base}")
            # what the gate left behind (coverage data, a build directory) is not the batch's work
            run(self.batch.path, "clean", "-qfdx")
            self.batch.link(self.main)  # the site config the push's own hooks read
            code, said = self._land()
            if code == 0:
                for m in merged:
                    self._done(m, "landed", "", log, self._commits(m, before))
                landed = [ln for ln in said.splitlines() if ln.startswith("Landed")]
                print(f"  {landed[0] if landed else 'landed'}")
                return
            # first what is outside the batch: origin may already hold it, the owner's checkout
            # may be dirty, origin may not answer
            self._outside(merged, gated_head, before, log)
            moved = (
                out(self.main, "rev-parse", f"refs/heads/{self.base}") != self.gated_tip
            )
            if moved or out(self.batch.path, "rev-parse", "HEAD") != gated_head:
                print(
                    "  the base moved while gating: rebuilding the batch on the new base"
                )
                members = merged
                continue
            # the base did not move and nothing outside the batch refused it: split it like a red one
            refused = (
                "land refused it: " + (said.strip().splitlines() or ["no reason"])[0]
            )
            if len(merged) == 1:
                self._done(
                    merged[0], "handed-back", refused + "\n" + said.strip()[-2000:], log
                )
                return
            half = len(merged) // 2
            print(f"  batch of {len(merged)}: {refused}: splitting it")
            self.settle(merged[:half], depth + 1)
            self.settle(merged[half:], depth + 1)
            return
        print(
            "  the base kept moving: the batch stays ready for the next run",
            file=sys.stderr,
        )

    def run(self) -> int:
        with _queue_lock(self.qdir) as mine:
            if not mine:
                print(
                    "A land queue run is already in progress here; it takes every ready branch."
                )
                return 0
            ready = sorted(
                _records(self.qdir / "ready"),
                key=lambda r: _when(r, "queued_at"),
            )
            members: list[dict[str, object]] = []
            for r in ready:
                branch, head = str(r["branch"]), str(r.get("head") or "")
                now = out(
                    self.main,
                    "rev-parse",
                    "--verify",
                    "--quiet",
                    f"refs/heads/{branch}",
                )
                on_base = (
                    run(
                        self.main, "merge-base", "--is-ancestor", head, self.base
                    ).returncode
                    == 0
                )
                if head and on_base:
                    # landed, by an earlier run killed before its records, or by hand
                    self._done(
                        r, "landed", f"already on {self.base}", "", self._commits(r, "")
                    )
                    continue
                if now != head:
                    self._done(
                        r,
                        "stale",
                        f"{branch} moved after ready (now {now[:8] or 'gone'}): run ready again",
                    )
                    continue
                if (
                    run(
                        self.main, "merge-base", "--is-ancestor", head, self.base
                    ).returncode
                    == 0
                ):
                    self._done(r, "landed", f"already on {self.base}")
                    continue
                members.append(r)
            if not members:
                print("The land queue is empty: nothing is ready.")
                return 0
            print(
                f"Land queue: {len(members)} ready branch(es) on {self.base}; gate `{self.gate}`, status `{self.status}`"
            )
            try:
                self.settle(members)
                while self.pending:
                    later, self.pending = self.pending, []
                    self.settle(later)
            except _RUN_ERRORS as exc:
                print(f"  {exc}. Every branch stays ready.", file=sys.stderr)
                return 1
            finally:
                self.batch.release()
            return 0


def print_status(main: Path) -> int:
    qdir = queue_dir(main)
    ready = sorted(_records(qdir / "ready"), key=lambda r: _when(r, "queued_at"))
    done = sorted(_records(qdir / "done"), key=lambda r: _when(r, "at"))
    print(f"ready ({len(ready)}):")
    for r in ready:
        print(f"  {r['branch']} at {str(r.get('head'))[:8]}")
    print(f"done ({len(done)}):")
    for r in done:
        reason = str(r.get("reason") or "").splitlines()
        line = f"  {r.get('outcome')}: {r['branch']}" + (
            f": {reason[0]}" if reason else ""
        )
        if r.get("log") and r.get("outcome") != "landed":
            line += f" (log: {r['log']})"
        print(line)
        commits = r.get("commits")
        for c in commits if isinstance(commits, list) else []:
            print("    " + json.dumps(c))
    return 0


# ── the two commands, as `worktree.py` dispatches them ────────────────────────────────────────────


def cmd_ready(
    main_checkout: Callable[[Path], Path | None],
    blockers: Callable[[Path, Path], list[str]],
    base_branch: Callable[[Path], str],
) -> int:
    """`worktree.py ready`: the issue's branch, clean and rebased, recorded as ready."""
    here = Path(out(Path.cwd(), "rev-parse", "--show-toplevel") or Path.cwd())
    main = main_checkout(here)
    if main is None:
        print("not inside a git checkout with a .git directory", file=sys.stderr)
        return 2
    if here == main:
        print(
            "REFUSING: ready runs inside the issue's worktree, not the main checkout. "
            "Enter it first (EnterWorktree name=<ISSUE-KEY>).",
            file=sys.stderr,
        )
        return 2
    branch = out(here, "symbolic-ref", "--quiet", "--short", "HEAD")
    if not branch or branch == BATCH_BRANCH:
        print("REFUSING: the worktree must be on its issue's branch", file=sys.stderr)
        return 2
    held = blockers(here, main)
    if held:
        shown = "".join(f"  {line}\n" for line in held[:20])
        print(
            f"REFUSING: {here} has uncommitted changes: commit them, then run ready.\n{shown}",
            file=sys.stderr,
        )
        return 1
    return mark_ready(main, here, branch, base_branch(main))


def refuse_land(main: Path | None) -> int:
    """`worktree.py land` in a repo that declares `[agents] land = "queue"`: 1 with why, else 0.
    The queue itself lands through `cmd_land` directly, never this command."""
    if main is None or agents_setting(main, "land") != "queue":
        return 0
    print(
        'REFUSING: this repo lands through the land queue ([agents] land = "queue"): run '
        "`python3 .claude/hooks/worktree.py ready` here; the queue gates every ready branch "
        "together and lands them.",
        file=sys.stderr,
    )
    return 1


def cmd_queue(
    status_only: bool,
    where: tuple[
        Callable[[Path], Path | None], Callable[[Path], str], Callable[[Path], str]
    ],
    tools: tuple[
        Callable[[], int],
        Callable[[Path], list[str]],
        Callable[[Path, str], dict[str, object]],
    ],
) -> int:
    """`worktree.py queue`: gate every ready branch together and land the batch."""
    session_main, base_branch, checked_out = where
    main = session_main(Path.cwd())
    if main is None:
        print("not inside a git checkout with a .git directory", file=sys.stderr)
        return 2
    if status_only:
        return print_status(main)
    base = base_branch(main)
    if checked_out(main) != base:
        print(
            f"REFUSING: the main checkout ({main}) is not on {base}, the default branch: tell the "
            "owner, and run the queue once it is back.",
            file=sys.stderr,
        )
        return 1
    land, link, record = tools
    return Queue(main, base, land, link, record).run()
